TLM.f("Sancti/07-23",{"officium":"S. Apollinaris Episcopi et Martyris","rule":["vide C2;","Gloria"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:84; 3:87"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."},{"k":"ref","la":"Dan 3:57"},{"k":"text","la":"Benedícite, ómnia ópera Dómini, Dómino: laudáte et superexaltáte eum in sǽcula."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."}],"Oratio":[{"k":"text","la":"Deus, fidélium remunerátor animárum, qui hunc diem beáti Apollináris Sacerdótis tui martýrio consecrásti: tríbue nobis, quǽsumus, fámulis tuis; ut, cujus venerándam celebrámus festivitátem, précibus ejus indulgéntiam consequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Petri 5:1-11"},{"k":"text","la":"Caríssimi: Senióres, qui in vobis sunt, obsecro, consénior et testis Christi passiónum: qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum: neque turpis lucri grátia, sed voluntárie: neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Simíliter adolescéntes, súbditi estóte senióribus. Omnes autem ínvicem humilitátem insinuáte: quia Deus supérbis resístit, humílibus autem dat grátiam. Humiliámini ígitur sub poténti manu Dei, ut vos exáltet in témpore visitatiónis: omnem sollicitúdinem vestram projiciéntes in eum, quóniam ipsi cura est de vobis. Sobrii estóte, et vigiláte: quia adversárius vester diábolus tamquam leo rúgiens círcuit, quærens quem dévoret: cui resístite fortes in fide: scientes eándem passiónem ei, quæ in mundo est, vestræ fraternitáti fíeri. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 22:24-30"},{"k":"text","la":"In illo témpore: Facta est conténtio inter discípulos, quis eórum viderétur esse major. Dixit autem eis Jesus: Reges géntium dominántur eórum; et qui potestátem habent super eos, benéfici vocántur. Vos autem non sic: sed qui major est in vobis, fiat sicut minor: et qui præcéssor est, sicut ministrátor. Nam quis major est, qui recúmbit, an qui mínistrat? nonne qui recúmbit? Ego autem in médio vestrum sum, sicut qui mínistrat. Vos autem estis, qui permansístis mecum in tentatiónibus meis: et ego dispóno vobis, sicut dispósuii mihi Pater meus regnum, ut edátis et bibátis super mensam meam in regno meo: et sedeátis super thronos, judicántes duódecim tribus Israël."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Réspice, Dómine, propítius super hæc múnera: quæ pro beáti Sacerdótis et Martyris tui Apollináris commemoratióne deférimus, et pro nostris offensiónibus immolámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:20; 20:21"},{"k":"text","la":"Dómine, quinque talénta tradidísti mihi, ecce, ália quinque superlucrátus sum. Euge, serve bone et fidélis, quia in pauca fuísti fidélis, supra multa te constítuam, intra in gáudium Dómini tui."}],"Postcommunio":[{"k":"text","la":"Tua sancta suméntes, quǽsumus, Dómine, ut beáti Apollináris nos fóveant continuáta præsídia: quia non désinis propítius intuéri, quos tálibus auxíliis concésseris adjuvári."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6fc068ff728b99e0":{"t":"Dn 3, 84 et 87, Dn 3, 57\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga! (Dn 3, 57) Blagoslivljajte, sva djela Gospodnja, Gospodina, hvalite i uzvisujte ga dovijeka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga!","kn":"(Dan. 3, 84, 87). Blagosivajte Gospodina, svećenici Božji; hvalite Boga, sveti i ponizni srcem. (Dani. 3, 57) Blagosivajte Gospodina, sva djela Gospodnja, slavite ga i veličajte, u vjekove! Slava Ocu . . . Blagosivajte . . .","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"423558b0f4fbcea5":{"t":"<i>Pomolimo se</i>.\nBože, koji nagrađuješ duše vjernih i koji si ovaj dan posvetio mučeništvom blaženog Apolinara svećenika svoga, daj, molimo, slugama svojim da postignemo oproštenje. po molitvama onoga kojeg časnu svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, 'koji nagrađuješ vjerne duše i koji si ovaj dan posvetio mučeništvom svoga svećenika Apolinara, podaij, molimo, nama slugama svojim, da dostignemo oproštenje molitvama onoga, kojega slavimo časnu svetkovinu, po G. n.","knRef":"Kniewald 1942, str. 652–653 (snimka 327) (OCR)"},"d077edb8bef3560a":{"t":"1 Pt 5, 1-11\nČitanje Poslanice bl. Petra apostola. Predragi, ja svećenik kao i vi, i svjedok Kristovih patnja i dionik njegove slave, koja će se objaviti, molim svećenike medu nama: Pasite Božje stado koje vam je povjereno. Nadzirite dobrovoljno, kako hoće Bog, a ne primorani ni radi niskoga dobitka, nego rado. Ne vladajte se kao silnici, nego nastojite da postanete uzori svojem stadu. A kada se pojavi vrhovni pastir, primit ćete neuveli vijenac slave. Tako i vi, mladi, pokoravajte se pretpostavljenima. Svi nastojite da se ponizno vladate jedan prema drugome, jer se Bog protivi oholima, a poniznima daje svoju milost. Ponizite se, dakle, pod jakom Božjom rukom, da vas uzdigne u vrijeme pohoda. Svu svoju brigu prepustite njemu, jer se on skrbi za vas. Budite trijezni i bdijte, jer vaš protivnik đavao obilazi ričući kao lav i traži da proždire koga. Oduprite mu se jakom vjerom znajući da i vaša braća po svijetu podnose iste patnje. A Bog svih milosti, koji nas je pozvao u svoju vječnu slavu u Isusu Kristu, poslije kratka trpljenja usavršit će nas i utvrditi. Njemu slava i vlast u vijeke vjekova. Amen.","kn":"Čitanje poslanice bi. Petra apostola (I, 5, 1-11). Pređraigi! Svećenike među vama molim ja, svećenik kao 1 oni, i svjedok Kristovih patnja, i dionik njegove slave, koja će se O'bjaiviti: Pasite Božje staido, boje vam je povjereno. Nadzirite dragovoljno, kakoi hoće Bog, a ne prisiljeni, ne radi niskoga dobitka, nego rado; ne kao da gospodarite baštinom, nego da postanete iskreni uzori stada. A kada se pojavi vrhovni pastir, primit čete neuveli vijenac slave. Tako i vi, mlađi, budite pokorni svećenicima. Svi nastojte, da se ponizno vladate jedan prema drugomu, jer se Bog protivi oholima, a poniznima daje svoju milost. Ponizite se, dakle, pod silnom rukom Božjom, da vas povisi u vrijeme svoga pohoda. Prepustite njemu svu svoju brigu, jer se on brine za vas. Budite trijezni i bdijte, jer đavao, vaš protivnik, riče kao lav i obilazi tražeći da koga proždere. Oprite mu se jaki u vjeri i znajte, da vaša braća u svijetu podnose iste patnje. A Bog svake milosti, koji nas pozva na svoju vječnu slavu u Isusu Kristu, usavršit će nas, pojačati i utvrditi po kratkom trpljenju. Njemu slava i vlast u viijeke vjekova. Amen.","knRef":"Kniewald 1942, str. 652–653 (snimka 327) (OCR)"},"3c8f3a7a5b4b0733":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nZakleo se Gospodin i neće se pokajati: ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 88, 21-23). Izabrah Davida slu- ,gu moga i pomazah ga uljem svetim; jer ruka moja (Ppmoze njemu i moja ga mišica jača. Neprijatelj mu ne će ništa naškoditi i sin zloće ne će mu nauditi.\n\nAleluja, aleluja (Ps, 109, 4). Zakle se Gospodin i ne će se pokajati: Ti si svećenik dovijeka, po redu Melkisedekovu, aleluja.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"baebfa5f14a05f25":{"t":"Lk 22, 24-30\nSlijedi sveto Evanđelje po Luki. U ono vrijeme nastade među učenicima spor, tko je između njih veći. Zato im Isus reče: Nevjernički vladari zarobljavaju narode, koji ove silnike još nazivaju svojim dobrotvorima. Ali vi nemojte tako! Nego onaj koji je među vama veći neka bude kao manji, a koji je poglavar, neka bude kao sluga. Pitam vas, tko je veći, da li onaj koji sjedi za stolom ili koji dvori? Nije li veći onaj koji sjedi? Ja sam među vama kao sluga, a vi ste sa mnom ustrajali u mojim kušnjama. Kao što je meni moj Otac odredio kraljevstvo, tako određujem i ja vama, da jedete i pijete za mojim stolom u mojem kraljevstvu, da sjedite na prijestoljima i sudite dvanaest plemena izraelskih.","kn":"t Slijedi sv. evanđelje po Luki (22, 24-30). U ono vrijeme nasta među učenicima prepirka, tko je između njih veći. Zato lm Isus reče: Kraljevi na- roda zaeuznguju ih i gospodare svoje nazivaju dobrotvorima. A među vshia neka ne bude tako. Nego, koji je među vama veći, neka bude kao manji, i poglavar kao sluga. Jer tko je veći, onaj koji sjedi za stolom ili koji poslužuje? Zar ne onaj, koji sjedi? A ja sam među vama. kao onaj, ko.ji poslužuje, a vi ste sa mnom ustrajali u miojim kušnjama. Zato iprepuštam kraljevstvo ja vama, kao što je moj Otaic prepustio meni, da sa mnom za stolom jedete i pijete u mojemu kraljevstvu i .sjedite na prijestoljima i sudite dvanaest plemena Izraelovih.","knRef":"Kniewald 1942, str. 652–653 (snimka 327) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"bb77d217c91d9280":{"t":"Milostivo pogledaj, Gospodine, na ove darove koje na spomen blaženoga svećenika i mučenika tvoga Apolinara prinosimo i žrtvujemo za naše uvrede.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospođine, milostivio na ove darove, što Ti ih prinosimo slaveći spomen blaženog biskupa i mučenika Tvoga Apolinara i žrtvujući ih za naše grijehe, po G. n.","knRef":"Kniewald 1942, str. 654–655 (snimka 328) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"a54da8d793bb82be":{"t":"Mt 25, 20 i 21\nGospodaru, predao si mi pet talenata. S njima sam stekao još drugih pet. Dobro, slugo dobri i vjerni, budući da si bio u malom vjeran, postavit ću te nad mnogim. Uđi u veselje gospodara svoga.","kn":"(Mt. 25, 20). Gospodine, predao si mi pet talenata, evo sam još pet dobio s njima. Dobro, slugo dobri i vjerni, jer si bio u malome vjeran, nad mnogim ću te postaviti, uđi u veselje gospodara svojega!","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"c2495bf0741fd78f":{"t":"<i>Pomolimo se</i>.\nPrimajući tvoje svete tajne, molimo. Gospodine, da nas potpomaže neprestana zaštita blaženog Apolinara, jer ne prestaješ blago gledati na one kojima dopuštaš da ih pomaže takva pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primajući Tvoje svetinje molimo Te, Gospodinie da nas neprestano štiti zagovor blaženog Apolinara, jer ne prestaješ blago gledati na one, kojima dopuštaš pomoć takve zaštite, po G. n.","knRef":"Kniewald 1942, str. 654–655 (snimka 328) (OCR)"}}});
